package eval

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// Row is one (config, task, repeat) observation. JSON Lines: appending is atomic
// enough for a sequential sweep, a partial run stays readable, and adding a field
// later does not invalidate rows already written — which matters because this file
// accumulates across features rather than being regenerated by each.
type Row struct {
	RunAt  string `json:"run_at"`
	Config string `json:"config"` // human label for the serving config under test
	Repeat int    `json:"repeat"`

	// Harness names the agent loop a tier-2 row measured, and Profile the desk profile
	// it was scored under. Both are empty on tier-1 rows, which drive no harness and
	// make no claim about the desktop. A tier-2 row needs the profile beside the numbers
	// because two harnesses scored under different ones are not comparable, and one
	// harness may be admissible under only one of them.
	Harness string `json:"harness,omitempty"`
	Profile string `json:"profile,omitempty"`

	// Offline marks a run the harness made with no network but the loopback the model is
	// served on. It is a condition rather than a metric, and the vision wants at least
	// one path that holds under it, so it sits on the row rather than in a filename.
	Offline bool `json:"offline,omitempty"`

	// Toggles under test. Thinking is a string, not a bool, because "unset" is a
	// third state: it leaves the model's own template default alone.
	Thinking string `json:"thinking"`

	// The effort the thinking was done at. Empty means the model's own default was
	// left in force, which for Qwen3.8 is xhigh — so an empty value here is a
	// measurement of xhigh, not of "unset", and rows written before this field
	// existed are all xhigh whether they say so or not.
	ReasoningEffort string   `json:"reasoning_effort"`
	Sampling        Sampling `json:"sampling"`

	// What the server actually served, so a mislabelled config is detectable.
	ServedNCtx  int    `json:"served_n_ctx"`
	ServedModel string `json:"served_model"`

	// Forced is true when the preflight refused and the run was started anyway. Such a
	// row measured a machine the check judged unable to carry it, so it is marked rather
	// than averaged in with the rest.
	Forced bool `json:"forced,omitempty"`

	TaskID      string  `json:"task_id"`
	Kind        string  `json:"kind"`
	Outcome     Outcome `json:"outcome"`
	Detail      string  `json:"detail,omitempty"`
	FreeGB      float64 `json:"free_gb"`
	SwapDeltaMB float64 `json:"swap_delta_mb"`
	MemMeasured bool    `json:"mem_measured"`

	// Turns is how many requests a harness made to finish a task, counted at the server
	// rather than taken from the harness. Zero on tier-1 rows, which are one request by
	// construction, and on any run where the server could not be watched.
	Turns int `json:"turns,omitempty"`

	PromptTokens     int     `json:"prompt_tokens"`
	CachedTokens     int     `json:"cached_tokens"`
	CompletionTokens int     `json:"completion_tokens"`
	ReasoningChars   int     `json:"reasoning_chars"`
	PromptPerSecond  float64 `json:"prompt_per_second"`
	GenPerSecond     float64 `json:"gen_per_second"`
	WallSeconds      float64 `json:"wall_seconds"`

	// Decode isolated from prefill, and acceptance length, both as the task records
	// them. The *_measured flags carry "the instrument could not read this" separately
	// from a zero, because a speculative mechanism that is off and one that accepts
	// nothing produce the same number and mean opposite things.
	TTFTSeconds        float64 `json:"ttft_seconds,omitempty"`
	DecodeSeconds      float64 `json:"decode_seconds,omitempty"`
	DecodePerSecond    float64 `json:"decode_per_second,omitempty"`
	DecodeMeasured     bool    `json:"decode_measured"`
	AcceptanceLength   float64 `json:"acceptance_length,omitempty"`
	AcceptanceMeasured bool    `json:"acceptance_measured"`
	DraftN             int     `json:"draft_n,omitempty"`
	DraftAccepted      int     `json:"draft_accepted,omitempty"`

	// Session pairs a candidate with the baseline it is to be read against. An unpaired
	// before-and-after measures host drift as well as the change; rows sharing a session
	// were measured on one machine state, back to back, and only those may be divided.
	Session string `json:"session,omitempty"`
}

// ToolCallValid reports whether the model produced a syntactically valid, schema-
// conforming tool call — separately from whether it chose the right one. A config
// that emits parseable calls to the wrong tool has a reasoning problem; one that
// emits unparseable JSON has a format problem, and they take different fixes.
func (r Row) ToolCallValid() (valid, applicable bool) {
	if r.Kind != "toolcall" {
		return false, false
	}
	switch r.Outcome {
	case Pass, FailWrongTool, FailArgs:
		return true, true
	case FailNoCall, FailBadJSON:
		return false, true
	default:
		return false, false // server errors are not the model's doing
	}
}

// Now is the clock NewRow stamps rows with. A package variable rather than a
// parameter threaded through every call site: it is the only nondeterminism in the
// package, and a test that wants a fixed timestamp sets it directly.
var Now = func() time.Time { return time.Now().UTC() }

func NewRow(cfg string, repeat int, thinking, effort string, s Sampling, props ServerProps, kind string, res Result) Row {
	return Row{
		RunAt:            Now().Format(time.RFC3339),
		Config:           cfg,
		Repeat:           repeat,
		Thinking:         thinking,
		ReasoningEffort:  effort,
		Sampling:         s,
		ServedNCtx:       props.NCtx,
		ServedModel:      filepath.Base(props.ModelPath),
		TaskID:           res.TaskID,
		Kind:             kind,
		Outcome:          res.Outcome,
		Detail:           res.Detail,
		FreeGB:           res.FreeGB,
		SwapDeltaMB:      res.SwapDeltaMB,
		MemMeasured:      res.MemMeasured,
		PromptTokens:     res.PromptTokens,
		CachedTokens:     res.CachedTokens,
		CompletionTokens: res.CompletionTokens,
		ReasoningChars:   res.ReasoningChars,
		PromptPerSecond:  res.PromptPerSecond,
		GenPerSecond:     res.GenPerSecond,
		WallSeconds:      res.WallSeconds,

		TTFTSeconds:        res.TTFTSeconds,
		DecodeSeconds:      res.DecodeSeconds,
		DecodePerSecond:    res.DecodePerSecond,
		DecodeMeasured:     res.DecodeMeasured,
		AcceptanceLength:   res.AcceptanceLength,
		AcceptanceMeasured: res.AcceptanceMeasured,
		DraftN:             res.DraftN,
		DraftAccepted:      res.DraftAccepted,
	}
}

// AppendRow writes one row and syncs it. A sweep is a multi-hour unattended job on
// this hardware, so a row must survive the process dying halfway through it.
func AppendRow(path string, r Row) error { return AppendJSON(path, r) }

// AppendJSON is the same durability for a row of another shape. Later features record
// observations this Row cannot express, and they must not have to reimplement the sync
// to get the guarantee above.
func AppendJSON(path string, v any) error {
	if dir := filepath.Dir(path); dir != "." {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return err
		}
	}
	b, err := json.Marshal(v)
	if err != nil {
		return err
	}
	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	// Close is checked rather than deferred-and-dropped: this is a write path, and a
	// row that never reached disk would silently shorten a multi-hour sweep's results.
	if _, err := fmt.Fprintf(f, "%s\n", b); err != nil {
		_ = f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		_ = f.Close()
		return err
	}
	return f.Close()
}
